svg.script:
(async () => {
  const $ = s => document.querySelector(s);
  const chat = $("#chat"), input = $("#input"), stat = $("#stat"), bar = $("#bar");
  const MODEL = "SmolLM2-360M-Instruct-q4f16_1-MLC";
  const history = [{ role: "system", content: "You are Nova, a friendly, helpful and concise AI assistant." }];
  let engine = null, busy = false;

  function add(text, who) {
    const hero = $("#hero"); if (hero) hero.remove();
    const d = document.createElementNS("http://www.w3.org/1999/xhtml", "div");
    d.className = "msg " + who;
    if (text) d.textContent = text;
    chat.appendChild(d);
    chat.scrollTop = chat.scrollHeight;
    return d;
  }

  async function ask(text) {
    if (!text || busy) return;
    add(text, "user");
    if (!engine) { add("I'm still waking up, give me a few seconds...", "ai"); return; }
    busy = true;
    history.push({ role: "user", content: text });
    const bubble = add("", "ai");
    bubble.innerHTML = '<span class="dots"><span></span><span></span><span></span></span>';
    let full = "";
    try {
      const stream = await engine.chat.completions.create({ messages: history, stream: true });
      for await (const c of stream) {
        full += c.choices[0]?.delta?.content || "";
        bubble.textContent = full;
        chat.scrollTop = chat.scrollHeight;
      }
      history.push({ role: "assistant", content: full });
    } catch (e) { bubble.textContent = "Oops: " + e.message; }
    busy = false;
  }

  $("#form").addEventListener("submit", e => {
    e.preventDefault();
    const t = input.value.trim(); input.value = ""; ask(t);
  });
  document.querySelectorAll(".chip").forEach(c => c.addEventListener("click", () => ask(c.textContent)));

  if (!navigator.gpu) {
    stat.textContent = "Needs WebGPU: use desktop Chrome or Edge";
    return;
  }
  try {
    const webllm = await import("https://cdn.jsdelivr.net/npm/@mlc-ai/web-llm@0.2.79/+esm");
    engine = await webllm.CreateMLCEngine(MODEL, {
      initProgressCallback: p => {
        bar.style.width = Math.round(p.progress * 100) + "%";
        stat.textContent = "Loading brain... " + Math.round(p.progress * 100) + "%";
      }
    });
    stat.textContent = "Online and ready";
    $("#barwrap").style.display = "none";
  } catch (e) { stat.textContent = "Error: " + e.message; }
})();
